-- Створюємо таблиці
-- 1. Створюємо таблицю
DROP TABLE IF EXISTS "interactive_map" CASCADE;
CREATE TABLE "interactive_map" (
    "idInteractive" SERIAL NOT NULL,
    "map" TEXT,
    "api_customuser_id" BIGINT NOT NULL,
    PRIMARY KEY ("idInteractive", "api_customuser_id"),
    CONSTRAINT "fk_interactive_map_api_customuser1" 
        FOREIGN KEY ("api_customuser_id") 
        REFERENCES "api_customuser" ("id")
);

-- 2. Створення індексу
CREATE INDEX "idx_interactive_map_user" ON "interactive_map" ("api_customuser_id");

-- Вставка данних після створення таблиць
INSERT INTO "interactive_map" VALUES (7,'data:image/png;base64,',9);

-- Налаштування лічильника SERIAL
SELECT setval(pg_get_serial_sequence('interactive_map', 'idInteractive'), (SELECT MAX("idInteractive") FROM "interactive_map"));